'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var cfill = require( '@stdlib/blas/ext/base/cfill' ).ndarray;
var cscal = require( '@stdlib/blas/base/cscal' ).ndarray;
var realf = require( '@stdlib/complex/float32/real' );
var imagf = require( '@stdlib/complex/float32/imag' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var reinterpret = require( '@stdlib/strided/base/reinterpret-complex64' );
var muladd = require( '@stdlib/complex/float32/base/mul-add' ).assign;


// MAIN //

/**
* Performs the matrix-vector operation `y = α*A*x + β*y`, where `α` and `β` are complex scalars, `x` and `y` are `N` element complex vectors, and `A` is an `N` by `N` Hermitian matrix, supplied in packed form `AP`.
*
* @private
* @param {string} uplo - specifies whether `A` is an upper or lower triangular part of matrix is supplied.
* @param {NonNegativeInteger} N - number of elements along each dimension of `A`
* @param {Complex64} alpha - complex scalar constant
* @param {Complex64Array} AP - complex input matrix
* @param {integer} strideAP - `AP` stride length
* @param {NonNegativeInteger} offsetA - starting index for `A`
* @param {Complex64Array} x - first complex input vector
* @param {integer} strideX - `x` stride length
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Complex64} beta - complex scalar constant
* @param {Complex64Array} y - second complex input vector
* @param {integer} strideY - `y` stride length
* @param {NonNegativeInteger} offsetY - starting index for `y`
* @returns {Complex64Array} `y`
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
* var Complex64 = require( '@stdlib/complex/float32/ctor' );
*
* var A = new Complex64Array( [  ] );
* var x = new Complex64Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );
* var y = new Complex64Array( [ 3.0, 3.0, 2.0, 2.0, 1.0, 1.0 ] );
* var alpha = new Complex64( 0.5, 0.5 );
* var beta = new Complex64( 0.5, -0.5 );
*
* chpmv( 'lower', 3, alpha, A, 0, 0, x, 1, 0, beta, y, 1, 0 );
* // y => <Complex64Array>[ -10.0, 14.0, -11.0, 25.0, 14.0, 31.0 ]
*/
function chpmv( uplo, N, alpha, AP, strideAP, offsetA, x, strideX, offsetX, beta, y, strideY, offsetY ) { // eslint-disable-line max-params, max-len
	var realpha;
	var imalpha;
	var rebeta;
	var imbeta;
	var retmp1;
	var imtmp1;
	var retmp2;
	var imtmp2;
	var viewAP;
	var viewX;
	var viewY;
	var isrm;
	var cima;
	var sign;
	var sap;
	var oa2;
	var reap;
	var imap;
	var rex;
	var imx;
	var kk;
	var ix;
	var iy;
	var oa;
	var ox;
	var oy;
	var sx;
	var sy;
	var i0;
	var i1;
	var iap;
	var k;

	// Decompose scalars
	rebeta = realf( beta );
	imbeta = imagf( beta );
	realpha = realf( alpha );
	imalpha = imagf( alpha );

	// y = beta*y
	if ( rebeta === 0.0 && imbeta === 0.0 ) {
		cfill( N, 0.0, y, strideY, offsetY );
	} else if ( rebeta !== 1.0 || imbeta !== 0.0 ) {
		cscal( N, beta, y, strideY, offsetY );
	}

	// If alpha is zero, early return y
	if ( realpha === 0.0 && imalpha === 0.0 ) {
		return y;
	}

	// Reinterpret arrays to raw numeric views
	viewAP = reinterpret( AP, 0 );
	viewX = reinterpret( x, 0 );
	viewY = reinterpret( y, 0 );

	// Adjust sign to account for layout-dependent conjugation
	if ( isrm ) {
		sign = -1;
	} else {
		sign = 1;
	}

	// Vector indexing base
	oa = offsetA * 2;
	ox = offsetX * 2;
	oy = offsetY * 2;

	// Vector strides
	sap = strideAP * 2;
	sx = strideX * 2;
	sy = strideY * 2;

	kk = 0;

	if ( ( isrm && uplo === 'upper' ) || ( !isrm && uplo === 'lower' ) ) {
		for ( i1 = 0; i1 < N; i1++ ) {
			ix = ox + ( i1 * sx );
			rex = viewX[ ix ];
			imx = viewX[ ix + 1 ];
			retmp1 = f32( ( realpha * rex ) - ( imalpha * imx ) );
			imtmp1 = f32( ( realpha * imx ) + ( imalpha * rex ) );
			retmp2 = 0.0;
			imtmp2 = 0.0;
			// oa2 = oa + ( i1 * sa1 );
			iap = oa + ( kk * sap );
			reap = viewAP[ iap ];
			iy = oy + ( i1 * sy );
			viewY[ iy ] += f32( retmp1 * reap );
			viewY[ iy + 1 ] += f32( imtmp1 * reap );
			k = kk + 1;
			for ( i0 = i1 + 1; i0 < N; i0++ ) {
				iap = oa + ( k * sap );
				reap = viewAP[ iap ];
				imap = viewAP[ iap + 1 ];
				iy = oy + ( i0 * sy );
				muladd( retmp1, imtmp1, reap, imap, viewY[ iy ], viewY[ iy + 1 ], viewY, 1, iy ); // eslint-disable-line max-len
				ix = ox + ( i0 * sx );
				rex = viewX[ ix ];
				imx = viewX[ ix + 1 ];
				retmp2 += f32( ( reap * rex ) + ( imap * imx ) );
				imtmp2 += f32( ( reap * imx ) - ( imap * rex ) );
				k += 1;
			}
			muladd( realpha, imalpha, retmp2, imtmp2, viewY[ iy ], viewY[ iy + 1 ], viewY, 1, iy ); // eslint-disable-line max-len
			kk += ( N - i1 );
		}
		return y;
	}
}